import React, { useState } from 'react';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  TextField,
  TablePagination,
  Link,
} from '@mui/material';
import { useParams, useNavigate } from 'react-router-dom';
import DownloadIcon from '@mui/icons-material/Download';
import AdminNavbar from './admin-navbar';

// Sample consent data simulating your DB schema
const consentsByOrg = {
  'Housing Loan': [
    {
      id: 'uuid-1234-5678',
      company_name: 'Housing Loan',
      company_email: 'contact@retailera.com',
      company_mobile: '+1234567890',
      user_mobile: '+0987654321',
      user_email: 'user@example.com',
      user_aadhar: 'ENCRYPTED-AADHAR-HASH',
      purpose: 'Marketing',
      obtainValidConsent:'Free',
      file_name: 'marketing-consent.pdf',
      file_type: 'application/pdf',
      file_content: null, // Usually not sent to frontend directly for security
      current_status: 'ACCEPTED',
      requested_at: '2025-05-30T12:00:00Z',
      responded_at: '2025-06-01T09:30:00Z',
      revoked_at: null,
      expiry_date: '2026-06-01T23:59:59Z',
    },
    // Add more consent objects here
  ],
  // More orgs...
};

// DPDP Awareness Box for Consent List Admin View
function DPDPConsentListAwareness() {
  return (
    <Box
      sx={{
        width: '95%',
        margin: 'auto',
        mt: 2,
        mb: 4,
        p: 3,
        border: '1px solid #1565c0',
        borderRadius: 2,
        backgroundColor: '#e3f2fd',
        boxShadow: 1,
      }}
    >
      <Typography variant="h6" fontWeight="bold" gutterBottom>
        🛡️ DPDP Act Consent List Awareness for Admins
      </Typography>
      <Typography variant="body1" gutterBottom>
        This list displays the detailed consents provided by users to deparment under the <strong>Data Protection and Privacy (DPDP) Act</strong>.
      </Typography>
      <Typography variant="body1" gutterBottom>
        Admins should carefully review consent statuses and details, ensuring compliance with consent management, data privacy, and timely revocation or expiry actions.
      </Typography>
      <Typography variant="body1">
        Always verify the legitimacy of consents and respond promptly to any grievances or discrepancies.
      </Typography>
    </Box>
  );
}

export function ConsentListPage() {
  const { orgId } = useParams();
  const navigate = useNavigate();

  const orgConsents = consentsByOrg[orgId] || [];

  // Search, Pagination
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);

  const filteredConsents = orgConsents.filter((consent) =>
    consent.purpose.toLowerCase().includes(searchTerm.toLowerCase()) ||
    consent.current_status.toLowerCase().includes(searchTerm.toLowerCase()) ||
    consent.company_email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    consent.user_email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    consent.file_name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const paginatedConsents = filteredConsents.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  const handleChangePage = (event, newPage) => setPage(newPage);
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const exportConsentsToCSV = () => {
    if (!filteredConsents.length) return;

    const headers = [
      'Consent ID',
      'Company Email',
      'Company Mobile',
      'User Mobile',
      'User Email',
      'User Aadhar (Encrypted)',
      'Purpose',
      'Obtain Valid Consent',
      'File Name',
      'Status',
      'Requested At',
      'Responded At',
      'Revoked At',
      'Expiry Date',
    ];

    const rows = filteredConsents.map((c) => [
      c.id,
      c.company_email,
      c.company_mobile || '',
      c.user_mobile || '',
      c.user_email || '',
      c.user_aadhar || '',
      c.purpose,
      c.file_name || '',
      c.current_status,
      new Date(c.requested_at).toLocaleString(),
      c.responded_at ? new Date(c.responded_at).toLocaleString() : '',
      c.revoked_at ? new Date(c.revoked_at).toLocaleString() : '',
      new Date(c.expiry_date).toLocaleDateString(),
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map((row) =>
        row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(',')
      ),
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `consents_${orgId}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };


  return (
    <>
      <AdminNavbar />
      {/* Awareness Box */}
      <DPDPConsentListAwareness />

      <Box sx={{ width: '95%', margin: 'auto', mt: 0 }}>
        <Typography variant="h5" fontWeight="bold" gutterBottom>
          Consent List for Department: {orgId}
        </Typography>

        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
          <Button variant="outlined" onClick={() => navigate(-1)}>
            Back to Departments
          </Button>
          <Button variant="outlined" onClick={exportConsentsToCSV}>
            <DownloadIcon /> Export CSV
          </Button>
        </Box>


        <TextField
          label="Search consents (purpose, status, emails, file)"
          variant="outlined"
          size="small"
          fullWidth
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="Search consents"
          sx={{ mb: 3 }}
        />

        <TableContainer component={Paper} elevation={4}>
          <Table size="small" sx={{ minWidth: 900 }}>
            <TableHead>
              <TableRow
                sx={{
                  background:
                    'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)',
                }}
              >
                <TableCell sx={{ color: 'white' }}>Requester Email</TableCell>
                <TableCell sx={{ color: 'white' }}>Requester Mobile</TableCell>
                <TableCell sx={{ color: 'white' }}>User Mobile</TableCell>
                <TableCell sx={{ color: 'white' }}>User Email</TableCell>
                {/* <TableCell sx={{ color: 'white' }}>User Aadhar (Encrypted)</TableCell> */}
                <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                <TableCell sx={{ color: 'white' }}>Obtain Valid Consent</TableCell>
                <TableCell sx={{ color: 'white' }}>File</TableCell>
                <TableCell sx={{ color: 'white' }}>Status</TableCell>
                <TableCell sx={{ color: 'white' }}>Requested At</TableCell>
                <TableCell sx={{ color: 'white' }}>Responded At</TableCell>
                <TableCell sx={{ color: 'white' }}>Revoked At</TableCell>
                <TableCell sx={{ color: 'white' }}>Expiry Date</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedConsents.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={14} align="center">
                    No consents found.
                  </TableCell>
                </TableRow>
              ) : (
                paginatedConsents.map((consent) => (
                  <TableRow key={consent.id}>
                    <TableCell>{consent.company_email}</TableCell>
                    <TableCell>{consent.company_mobile || 'N/A'}</TableCell>
                    <TableCell>{consent.user_mobile || 'N/A'}</TableCell>
                    <TableCell>{consent.user_email || 'N/A'}</TableCell>
                    {/* <TableCell>{consent.user_aadhar || 'N/A'}</TableCell> */}
                    <TableCell>{consent.purpose}</TableCell>
                    <TableCell>{consent.obtainValidConsent}</TableCell>
                    <TableCell>
                      {consent.file_name ? (
                        <Link
                          href={`https://example.com/files/${consent.file_name}`}
                          target="_blank"
                          rel="noopener"
                        >
                          {consent.file_name}
                        </Link>
                      ) : (
                        'N/A'
                      )}
                    </TableCell>
                    <TableCell>{consent.current_status}</TableCell>
                    <TableCell>{new Date(consent.requested_at).toLocaleString()}</TableCell>
                    <TableCell>
                      {consent.responded_at
                        ? new Date(consent.responded_at).toLocaleString()
                        : 'N/A'}
                    </TableCell>
                    <TableCell>
                      {consent.revoked_at
                        ? new Date(consent.revoked_at).toLocaleString()
                        : 'N/A'}
                    </TableCell>
                    <TableCell>{new Date(consent.expiry_date).toLocaleDateString()}</TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>

          <TablePagination
            rowsPerPageOptions={[5, 10, 25]}
            component="div"
            count={filteredConsents.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
            labelRowsPerPage="Rows per page"
          />
        </TableContainer>
      </Box>
    </>
  );
}
