import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TextField,
  TablePagination,
  Button,
} from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import OrgNavbar from './organization-navbar'; // assuming you have a separate navbar for orgs

function DPDPInfoBox() {
  return (
    <Box
      sx={{
        width: '97%',
        margin: 'auto',
        mb: 3,
        p: 2,
        border: '1px solid #e0e0e0',
        borderRadius: 2,
        backgroundColor: '#fff8e1',
        boxShadow: 1,
      }}
    >
      <Typography variant="body1" fontWeight="bold" gutterBottom>
        🛡️ DPDP Awareness
      </Typography>
      <Typography variant="body2">
        The <strong>DPDP Act</strong> ensures transparency and accountability in your deparment's data processing activities. All audit logs for consent handling, data usage, and grievances are maintained here.
      </Typography>
    </Box>
  );
}

function OrganizationAuditLogsPage() {
  const [logs, setLogs] = useState([
    {
      id: 1,
      timestamp: '2025-06-01 09:20 AM',
      action: 'Consent Received',
      user: 'User123',
      purpose: 'Name Verification',
      details: 'User granted consent for name verification.',
      metadata: 'IP: 192.168.1.1 | Device: Chrome on Android | Location: Bangalore',
    },
    {
      id: 2,
      timestamp: '2025-06-05 02:15 PM',
      action: 'Data Shared',
      user: 'User456',
      purpose: 'KYC',
      details: 'Shared anonymized data for analytics purposes.',
      metadata: 'IP: 10.10.0.5 | Device: Safari on iOS  | Location: Bangalore',
    },
    {
      id: 3,
      timestamp: '2025-06-07 11:05 AM',
      action: 'Grievance Resolved',
      user: 'User789',
      purpose: 'Deposits',
      details: 'Resolved grievance about unauthorized data usage.',
      metadata: 'IP: 172.16.0.2 | Device: Firefox on Linux  | Location: Bangalore',
    },
    // Add more logs as needed...
  ]);

  const [searchText, setSearchText] = useState('');
  const [filteredLogs, setFilteredLogs] = useState(logs);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  useEffect(() => {
    const filtered = logs.filter((log) =>
      [log.user, log.purpose, log.action, log.details, log.metadata]
        .some((field) => field.toLowerCase().includes(searchText.toLowerCase()))
    );
    setFilteredLogs(filtered);
    setPage(0);
  }, [searchText, logs]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleExportCSV = () => {
    const headers = ['Timestamp', 'Action', 'User', 'Purpose', 'Details', 'Metadata'];
    const rows = filteredLogs.map((log) => [
      log.timestamp,
      log.action,
      log.user,
      log.purpose,
      log.details,
      log.metadata,
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map((row) =>
        row.map((value) => `"${(value || '').replace(/"/g, '""')}"`).join(',')
      ),
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'organization_audit_logs.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Box>
      <OrgNavbar />
      <Box sx={{ width: '90%', margin: 'auto', mt: 4 }}>
        <Typography variant="h6" fontWeight="bold" gutterBottom>
          📝 Audit Logs
        </Typography>
        <Typography variant="body2" sx={{ mb: 3 }}>
          View a chronological log of your organization's actions related to consents, data sharing, and grievance handling for transparency and compliance.
        </Typography>
        <DPDPInfoBox />

        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
          <TextField
            label="Search Logs"
            variant="outlined"
            size="small"
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            placeholder="Search by user, purpose, action, details, or metadata"
            sx={{ mr: 2, width: '88%' }}
          />
          <Box>
            <Button size="small" variant="outlined" onClick={handleExportCSV} style={{ padding: '8px 16px' }}>
              <DownloadIcon /> Export CSV
            </Button>
          </Box>
        </Box>

        <TableContainer component={Paper} elevation={4}>
          <Table>
            <TableHead>
              <TableRow sx={{ background: 'linear-gradient(90deg, #1e3c72, #2a5298)' }}>
                <TableCell sx={{ color: 'white' }}>Timestamp</TableCell>
                <TableCell sx={{ color: 'white' }}>Action</TableCell>
                <TableCell sx={{ color: 'white' }}>User</TableCell>
                <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                <TableCell sx={{ color: 'white' }}>Details</TableCell>
                <TableCell sx={{ color: 'white' }}>Metadata</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredLogs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    No audit logs found.
                  </TableCell>
                </TableRow>
              ) : (
                filteredLogs
                  .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                  .map((log) => (
                    <TableRow key={log.id}>
                      <TableCell>{log.timestamp}</TableCell>
                      <TableCell>{log.action}</TableCell>
                      <TableCell>{log.user}</TableCell>
                      <TableCell>{log.purpose}</TableCell>
                      <TableCell>{log.details}</TableCell>
                      <TableCell>{log.metadata}</TableCell>
                    </TableRow>
                  ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          component="div"
          count={filteredLogs.length}
          page={page}
          onPageChange={handleChangePage}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          rowsPerPageOptions={[5, 10, 25]}
          sx={{ mt: 2 }}
        />
      </Box>
    </Box>
  );
}

export default OrganizationAuditLogsPage;
