import React, { useState } from 'react';
import {
  Box,
  Typography,
  Card,
  Table,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  IconButton,
  Menu,
  MenuItem,
  TablePagination,
} from '@mui/material';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import { v4 as uuidv4 } from 'uuid';
import AdminNavbar from './admin-navbar';
import OrgNavbar from './organization-navbar';

const roles = [
  { value: 'admin', label: 'Admin' },
  { value: 'consent_manager', label: 'Consent Manager' },
  { value: 'grievance_manager', label: 'Grievance Manager' },
];

const sampleOrgUsers = [
  { id: uuidv4(), name: 'Asha R', email: 'asha@healthcare.com', role: 'admin', org: 'HealthCare Inc.' },
  { id: uuidv4(), name: 'Ben T', email: 'ben@edulearn.com', role: 'consent_manager', org: 'EduLearn' },
  { id: uuidv4(), name: 'Clara L', email: 'clara@fittrack.com', role: 'grievance_manager', org: 'FitTrack' },
  { id: uuidv4(), name: 'David S', email: 'david@datacorp.com', role: 'admin', org: 'DataSecure Corp.' },
  { id: uuidv4(), name: 'Elena W', email: 'elena@banksmart.com', role: 'consent_manager', org: 'BankSmart' },
  { id: uuidv4(), name: 'Farhan M', email: 'farhan@travelgo.com', role: 'grievance_manager', org: 'TravelGo' },
  { id: uuidv4(), name: 'Grace H', email: 'grace@mediconnect.com', role: 'admin', org: 'MediConnect' },
  { id: uuidv4(), name: 'Harry P', email: 'harry@learnhub.com', role: 'grievance_manager', org: 'LearnHub' },
  { id: uuidv4(), name: 'Ishita N', email: 'ishita@securepay.com', role: 'admin', org: 'SecurePay' },
  { id: uuidv4(), name: 'Jay V', email: 'jay@cleandata.com', role: 'consent_manager', org: 'CleanData Labs' },
];

function ManageOrgUsersPage() {
  const [users, setUsers] = useState(sampleOrgUsers);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(0);
  const rowsPerPage = 5;

  const [anchorEl, setAnchorEl] = useState(null);
  const [menuUserId, setMenuUserId] = useState(null);

  const [formMode, setFormMode] = useState('add');
  const [openDialog, setOpenDialog] = useState(false);
  const [currentUser, setCurrentUser] = useState({
    id: '',
    name: '',
    email: '',
    role: 'admin',
    org: '',
  });

  const handleOpenAdd = () => {
    setFormMode('add');
    setCurrentUser({ id: '', name: '', email: '', role: 'admin', org: '' });
    setOpenDialog(true);
  };

  const handleOpenEdit = (user) => {
    setFormMode('edit');
    setCurrentUser(user);
    setOpenDialog(true);
    handleCloseMenu();
  };

  const handleDelete = (id) => {
    setUsers(users.filter((u) => u.id !== id));
    handleCloseMenu();
  };

  const handleSave = () => {
    if (formMode === 'add') {
      setUsers([...users, { ...currentUser, id: uuidv4() }]);
    } else {
      setUsers(users.map((u) => (u.id === currentUser.id ? currentUser : u)));
    }
    setOpenDialog(false);
  };

  const handleOpenMenu = (event, userId) => {
    setAnchorEl(event.currentTarget);
    setMenuUserId(userId);
  };

  const handleCloseMenu = () => {
    setAnchorEl(null);
    setMenuUserId(null);
  };

  const filteredUsers = users.filter(
    (u) =>
      u.name.toLowerCase().includes(search.toLowerCase()) ||
      u.email.toLowerCase().includes(search.toLowerCase()) ||
      u.org.toLowerCase().includes(search.toLowerCase())
  );

  const paginatedUsers = filteredUsers.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  return (
    <Box>
      <OrgNavbar />
      <Box sx={{ mt: 4, px: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Box>
            <Typography variant="h4" fontWeight="bold">Manage Users</Typography>
            <Typography variant="subtitle1" color="textSecondary">
              Add, edit, and remove users
            </Typography>
          </Box>
          <Button variant="contained" onClick={handleOpenAdd}>Add User</Button>
        </Box>

        <TextField
          label="Search user by name, email"
          fullWidth
          size="small"
          sx={{ mb: 2 }}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <Card>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Name</TableCell>
                <TableCell>Email</TableCell>
                {/* <TableCell>Organization</TableCell> */}
                <TableCell>Role</TableCell>
                <TableCell align="right"></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedUsers.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>{user.name}</TableCell>
                  <TableCell>{user.email}</TableCell>
                  {/* <TableCell>{user.org}</TableCell> */}
                  <TableCell>{roles.find((r) => r.value === user.role)?.label}</TableCell>
                  <TableCell align="right">
                    <IconButton onClick={(e) => handleOpenMenu(e, user.id)}>
                      <MoreVertIcon />
                    </IconButton>
                    <Menu
                      anchorEl={anchorEl}
                      open={menuUserId === user.id}
                      onClose={handleCloseMenu}
                    >
                      <MenuItem onClick={() => handleOpenEdit(user)}>Edit</MenuItem>
                      <MenuItem onClick={() => handleDelete(user.id)}>Delete</MenuItem>
                    </Menu>
                  </TableCell>
                </TableRow>
              ))}
              {paginatedUsers.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} align="center">
                    No matching users found.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>

          <TablePagination
            component="div"
            count={filteredUsers.length}
            page={page}
            onPageChange={(e, newPage) => setPage(newPage)}
            rowsPerPage={rowsPerPage}
            rowsPerPageOptions={[rowsPerPage]}
          />
        </Card>
      </Box>

      {/* Add/Edit Dialog */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{formMode === 'add' ? 'Add Organization User' : 'Edit User'}</DialogTitle>
        <DialogContent>
          <TextField
            label="Name"
            fullWidth
            sx={{ my: 1 }}
            value={currentUser.name}
            onChange={(e) => setCurrentUser({ ...currentUser, name: e.target.value })}
          />
          <TextField
            label="Email"
            fullWidth
            sx={{ my: 1 }}
            value={currentUser.email}
            onChange={(e) => setCurrentUser({ ...currentUser, email: e.target.value })}
          />
          {/* <TextField
            label="Organization"
            fullWidth
            sx={{ my: 1 }}
            value={currentUser.org}
            onChange={(e) => setCurrentUser({ ...currentUser, org: e.target.value })}
          /> */}
          <TextField
            select
            label="Role"
            fullWidth
            sx={{ my: 1 }}
            value={currentUser.role}
            onChange={(e) => setCurrentUser({ ...currentUser, role: e.target.value })}
          >
            {roles.map((r) => (
              <MenuItem key={r.value} value={r.value}>{r.label}</MenuItem>
            ))}
          </TextField>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleSave}>
            {formMode === 'add' ? 'Add' : 'Update'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

export default ManageOrgUsersPage;
