import React, { useState, useRef, useEffect } from 'react';
import {
  Box,
  TextField,
  Button,
  Typography,
  useMediaQuery,
  useTheme,
  Container,
  Divider,
  Link,
  Select,
  MenuItem,
  InputLabel,
  FormControl,
  FormHelperText,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import SecurityImg from '../static/images/login-security.jpg'; // Update path if needed



function DPDPInfoBox() {
  return (
    <Box
      sx={{
        mt: 4,
        p: 4,
        border: '1px solid #1976d2',
        borderRadius: 3,
        backgroundColor: '#e3f2fd',
        boxShadow: 3,
      }}
    >
      <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0d47a1', mb: 2 }}>
        Your Data, Your Control – Powered by the DPDP Act
      </Typography>
      <Typography variant="body1" color="text.primary" sx={{ mb: 2 }}>
        This centralized <strong>Consent Management System (CMS)</strong> is designed in compliance with the{' '}
        <strong>Digital Personal Data Protection (DPDP) Act, 2023</strong>. It enables individuals and organizations to manage, review, and update their data sharing consents in a secure and transparent way.
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        You have full control over how your personal data is collected and used. The DPDP Act empowers you to give, deny, or withdraw consent at any time.
      </Typography>
      <Link href="/dpdp-info" target="_blank" rel="noopener" underline="hover">
        Learn more about your data rights →
      </Link>
    </Box>
  );
}

function OrganizationAPIRegistration() {
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const [form, setForm] = useState({
    name: '',
    email: '',
    contact: '',
    pan: null,
    category: '',
    taxId: '',
    dob: '',
    aadhar: '',
    otp: '',
  });

  const [otpSent, setOtpSent] = useState(false);
  const [apiKey, setApiKey] = useState('');
  const [containerHeight, setContainerHeight] = useState('auto');

  const formRef = useRef(null);
  const imageRef = useRef(null);

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    setForm({
      ...form,
      [name]: files ? files[0] : value,
    });
  };

  const handleGenerateAPI = () => {
    const { name, email, contact, pan, category, taxId, dob, aadhar } = form;
    if (!name || !email || !contact || !pan || !category || !taxId || !dob || !aadhar) {
      return alert('All fields including PAN document are required.');
    }
    setOtpSent(true);
    alert(`OTP sent to ${form.email}`);
  };

  const handleVerifyOtp = () => {
    if (form.otp === '123456') {
      setApiKey('API-KEY-XYZ-123456');
    } else {
      alert('Invalid OTP');
    }
  };

  useEffect(() => {
    if (formRef.current && imageRef.current) {
      setContainerHeight(Math.max(formRef.current.offsetHeight, imageRef.current.offsetHeight));
    }
  }, [form, otpSent, apiKey, isMobile]);

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Box
        sx={{
          display: 'flex',
          flexDirection: isMobile ? 'column' : 'row',
          border: '1px solid #ccc',
          borderRadius: 3,
          boxShadow: 3,
          overflow: 'hidden',
          height: isMobile ? 'auto' : containerHeight,
          bgcolor: '#fff',
        }}
      >
        {/* Left DPDP Info Section */}
        <Box
          ref={imageRef}
          sx={{
            flex: 1,
            p: 2,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
            backgroundColor: '#fafafa',
          }}
        >
          <DPDPInfoBox />
          {/* <img
            src={SecurityImg}
            alt="DPDP Top"
            style={{ maxWidth: '100%', borderRadius: '8px 8px 0 0' }}
          />
           */}
          {/* <img
            src={DPDPBottomImage}
            alt="DPDP Bottom"
            style={{ maxWidth: '100%', borderRadius: '0 0 8px 8px' }}
          /> */}
        </Box>

        {/* Right Form Section */}
        <Box
          ref={formRef}
          sx={{
            flex: 1,
            p: 4,
            display: 'flex',
            flexDirection: 'column',
            gap: 2,
            boxSizing: 'border-box',
          }}
        >
          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
            Organization API Registration
          </Typography>

          <TextField label="Organization Name" name="name" fullWidth value={form.name} onChange={handleChange} />
          <TextField label="Email ID" name="email" fullWidth value={form.email} onChange={handleChange} />
          <TextField label="Contact Number" name="contact" fullWidth value={form.contact} onChange={handleChange} />

          <FormControl fullWidth>
            <InputLabel>Category</InputLabel>
            <Select
              name="category"
              value={form.category}
              onChange={handleChange}
              label="Category"
            >
              <MenuItem value="banking">Banking</MenuItem>
              <MenuItem value="financial">Financial</MenuItem>
              <MenuItem value="educational">Educational</MenuItem>
            </Select>
            <FormHelperText>Choose the organization's category</FormHelperText>
          </FormControl>

          <TextField label="Tax ID" name="taxId" fullWidth value={form.taxId} onChange={handleChange} />
          <TextField label="DOI" name="dob" type="date" fullWidth value={form.dob} onChange={handleChange} InputLabelProps={{ shrink: true }} />
          {/* <TextField label="Aadhar Number" name="aadhar" fullWidth value={form.aadhar} onChange={handleChange} /> */}

          <Box>
            <Button variant="outlined" component="label">
              Upload PAN Document
              <input
                type="file"
                hidden
                name="pan"
                onChange={handleChange}
                accept="application/pdf,image/*"
              />
            </Button>
            {form.pan && (
              <Typography variant="caption" sx={{ mt: 1, display: 'block', color: 'text.secondary' }}>
                Uploaded File: <strong>{form.pan.name}</strong>
              </Typography>
            )}
          </Box>

          {!otpSent ? (
            <Button variant="contained" color="primary" onClick={handleGenerateAPI}>
              Generate API
            </Button>
          ) : !apiKey ? (
            <>
              <TextField label="Enter OTP" name="otp" fullWidth value={form.otp} onChange={handleChange} />
              <Button variant="contained" color="success" onClick={handleVerifyOtp}>
                Verify OTP
              </Button>
            </>
          ) : (
            <Box sx={{ mt: 2 }}>
              <Typography variant="body1" color="success.main">
                API Key Generated:
              </Typography>
              <Typography
                variant="body2"
                sx={{ fontFamily: 'monospace', backgroundColor: '#e0f2f1', p: 1, borderRadius: 1 }}
              >
                {apiKey}
              </Typography>
            </Box>
          )}
          <Box sx={{ textAlign: 'right' }}>
            Already Registered?{' '}
            <i
              style={{ color: 'blue', cursor: 'pointer' }}
              onClick={() => navigate('/')}
            >
              Login
            </i>
          </Box>
          <Typography variant="caption" sx={{ mt: 'auto', color: 'text.secondary', pt: 2 }}>
            By registering, you acknowledge and agree to our compliance with the DPDP Act and the protection of your data rights.
          </Typography>
        </Box>
      </Box>
    </Container>
  );
}

export default OrganizationAPIRegistration;
