import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TextField,
  TablePagination,
  Button
} from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import AdminNavbar from './admin-navbar';

function DPDPInfoBox() {
  return (
    <Box
      sx={{
        width: '97%',
        margin: 'auto',
        mb: 3,
        p: 2,
        border: '1px solid #e0e0e0',
        borderRadius: 2,
        backgroundColor: '#fff8e1',
        boxShadow: 1,
      }}
    >
      <Typography variant="body1" fontWeight="bold" gutterBottom>
        🛡️ DPDP Oversight (Admin View)
      </Typography>
      <Typography variant="body2">
        As the owner of this application, you have full visibility into all audit logs, including user and deparment actions. This ensures compliance, accountability, and transparency under the <strong>DPDP Act</strong>.
      </Typography>
    </Box>
  );
}

function AdminAuditLogs() {
  const [logs, setLogs] = useState([
    {
      id: 1,
      timestamp: '2025-06-01 09:15 AM',
      action: 'Consent Given',
      user: 'User123',
      organization: 'Housing Loan',
      purpose: 'Name Verification',
      details: 'User granted consent for name verification.',
      metadata: 'IP: 192.168.1.1 | Device: Chrome on Windows | Location: Mumbai',
    },
    {
      id: 2,
      timestamp: '2025-06-05 11:00 AM',
      action: 'Data Shared',
      user: 'User456',
      organization: 'Housing Loan',
      purpose: 'Name Verification',
      details: 'shared data for name verification.',
      metadata: 'IP: 10.0.0.1 | Device: Safari on iOS | Location: Bangalore',
    },
    {
      id: 3,
      timestamp: '2025-06-07 03:20 PM',
      action: 'Grievance Raised',
      user: 'User789',
      organization: 'Account Opening',
      purpose: 'KYC',
      details: 'User raised grievance about data misuse.',
      metadata: 'IP: 172.16.0.2 | Device: Firefox on Linux | Location: Mumbai',
    },
    {
      id: 4,
      timestamp: '2025-06-08 09:30 AM',
      action: 'Grievance Resolved',
      user: 'User789',
      organization: 'Account Opening',
      purpose: 'KYC',
      details: 'Bank resolved the user’s grievance.',
      metadata: 'IP: 192.168.100.1 | Device: Edge on Windows | Location: Thane',
    },
  ]);

  const [searchText, setSearchText] = useState('');
  const [filteredLogs, setFilteredLogs] = useState(logs);

  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  useEffect(() => {
    const filtered = logs.filter(
      (log) =>
        (log.user && log.user.toLowerCase().includes(searchText.toLowerCase())) ||
        (log.organization && log.organization.toLowerCase().includes(searchText.toLowerCase())) ||
        (log.purpose && log.purpose.toLowerCase().includes(searchText.toLowerCase())) ||
        (log.action && log.action.toLowerCase().includes(searchText.toLowerCase())) ||
        (log.details && log.details.toLowerCase().includes(searchText.toLowerCase())) ||
        (log.metadata && log.metadata.toLowerCase().includes(searchText.toLowerCase()))
    );
    setFilteredLogs(filtered);
    setPage(0);
  }, [searchText, logs]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const exportLogsToCSV = () => {
    if (!filteredLogs.length) return;

    const headers = ['ID', 'Timestamp', 'Action', 'User', 'Organization', 'Purpose', 'Details', 'Metadata'];
    const rows = filteredLogs.map((log) => [
      log.id,
      log.timestamp,
      log.action,
      log.user,
      log.organization,
      log.purpose,
      log.details,
      log.metadata,
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map((row) =>
        row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(',')
      ),
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'dpdp_audit_logs.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Box>
      <AdminNavbar />
      <Box sx={{ width: '90%', margin: 'auto', mt: 4 }}>
        <Typography variant="h6" fontWeight="bold" gutterBottom>
          📝 Audit Logs
        </Typography>
        <Typography variant="body2" sx={{ mb: 3 }}>
          View system-wide audit logs of users and deparment to ensure full compliance and traceability.
        </Typography>
        <DPDPInfoBox />

        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
          <TextField
            label="Search Logs"
            variant="outlined"
            size="small"
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            placeholder="Search by user, department, purpose, action, details, or metadata"
            sx={{ mr: 2, width: '88%' }}
          />
          <Box>
            <Button
              size="small"
              variant="outlined"
              onClick={exportLogsToCSV}
              style={{ padding: '8px 16px' }}
            >
              <DownloadIcon /> Export CSV
            </Button>
          </Box>
        </Box>

        <TableContainer component={Paper} elevation={4}>
          <Table>
            <TableHead>
              <TableRow sx={{ background: 'linear-gradient(90deg, #1e3c72, #2a5298)' }}>
                <TableCell sx={{ color: 'white' }}>Timestamp</TableCell>
                <TableCell sx={{ color: 'white' }}>Action</TableCell>
                <TableCell sx={{ color: 'white' }}>User</TableCell>
                <TableCell sx={{ color: 'white' }}>Department</TableCell>
                <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                <TableCell sx={{ color: 'white' }}>Details</TableCell>
                <TableCell sx={{ color: 'white' }}>Metadata</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredLogs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} align="center">
                    No audit logs found.
                  </TableCell>
                </TableRow>
              ) : (
                filteredLogs
                  .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                  .map((log) => (
                    <TableRow key={log.id}>
                      <TableCell>{log.timestamp}</TableCell>
                      <TableCell>{log.action}</TableCell>
                      <TableCell>{log.user}</TableCell>
                      <TableCell>{log.organization}</TableCell>
                      <TableCell>{log.purpose}</TableCell>
                      <TableCell>{log.details}</TableCell>
                      <TableCell>{log.metadata}</TableCell>
                    </TableRow>
                  ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          component="div"
          count={filteredLogs.length}
          page={page}
          onPageChange={handleChangePage}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          rowsPerPageOptions={[5, 10, 25]}
          sx={{ mt: 2 }}
        />
      </Box>
    </Box>
  );
}

export default AdminAuditLogs;
