import React from 'react';
import {
  Box,
  Typography,
  Card,
  Grid,
  Table,
  TableBody,
  TableRow,
  TableCell,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
} from 'chart.js';
import OrgNavbar from './organization-navbar';

ChartJS.register(ArcElement, Tooltip);

function ColorBox({ color }) {
  return (
    <Box
      sx={{
        width: 12,
        height: 12,
        borderRadius: '4px',
        backgroundColor: color,
        display: 'inline-block',
        mr: 1,
      }}
    />
  );
}

function DPDPOrgAwarenessBox() {
  return (
    <Box
      sx={{
        flex: 1,
        p: 3,
        border: '1px solid rgb(17, 1, 1)',
        backgroundColor: '#f9f9f9',
        borderRadius: 2,
        boxShadow: 1,
        minWidth: 280,
      }}
    >
      <Typography variant="h6" fontWeight="bold" gutterBottom color="primary">
        🛡️ Comply with the DPDP Act
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        ✅ Ensure lawful data processing.
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        ✅ Provide transparent data practices.
      </Typography>
      <Typography variant="body2">
        🔒 Maintain records of consent and usage.
      </Typography>
    </Box>
  );
}

function OrgResponsibilitiesBox() {
  return (
    <Box
      sx={{
        flex: 1,
        p: 3,
        border: '1px solid rgb(17, 1, 1)',
        backgroundColor: '#ffffff',
        borderRadius: 2,
        boxShadow: 1,
        minWidth: 280,
      }}
    >
      <Typography variant="h6" fontWeight="bold" gutterBottom>
        🏢 Your Responsibilities
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        • Collect and manage user consent.
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        • Respond to data access/revocation requests.
      </Typography>
      <Typography variant="body2">
        • Maintain data transparency and security.
      </Typography>
    </Box>
  );
}

function OrganizationDashboard() {
  const theme = useTheme();
  const isSmallScreen = useMediaQuery(theme.breakpoints.down('sm'));

  const consentStats = {
    total: 128,
    approved: 70,
    pending: 30,
    rejected: 18,
    revoked: 10,
  };

  const grievanceStats = {
    total: 20,
    pending: 5,
    resolved: 15,
  };

  const consentChartData = {
    labels: [],
    datasets: [
      {
        data: [
          consentStats.approved,
          consentStats.pending,
          consentStats.rejected,
          consentStats.revoked,
        ],
        backgroundColor: ['#4caf50', '#ff9800', '#f44336', '#9e9e9e'],
        borderWidth: 1,
      },
    ],
  };

  const grievanceChartData = {
    labels: [],
    datasets: [
      {
        data: [grievanceStats.pending, grievanceStats.resolved],
        backgroundColor: ['#ffb300', '#4caf50'],
        borderWidth: 1,
      },
    ],
  };

  const chartOptions = {
    plugins: {
      legend: { display: false },
    },
    maintainAspectRatio: false,
  };

  return (
    <Box>
      <OrgNavbar />
      <Box sx={{ mt: 3, textAlign: 'center' }}>
        <Typography variant="h4" fontWeight="bold">
          👋 Hi, Housing Loan!
        </Typography>
        <Typography variant="subtitle1" color="textSecondary">
          Welcome to CMS, you can manage user consent here
        </Typography>
      </Box>

      {/* Chart + Table Grid */}
      <Box sx={{ mt: 5, px: 3 }}>
        <Grid container spacing={4} justifyContent="center">
          {/* Consent */}
          <Grid item xs={12} md={6}>
            <Card elevation={5} sx={{ p: 3, display: 'flex', flexDirection: isSmallScreen ? 'column' : 'row', gap: 3 }}>
              <Box sx={{ width: isSmallScreen ? '100%' : '50%', height: 250 }}>
                <Doughnut data={consentChartData} options={chartOptions} />
              </Box>
              <Box sx={{ flex: 1 }}>
                <Typography color="primary" gutterBottom sx={{fontSize:'16px',textAlign:'center'}}>
                  Consent Summary
                </Typography>
                <Table size="small">
                  <TableBody>
                    <TableRow>
                      <TableCell></TableCell>
                      <TableCell>Total</TableCell>
                      <TableCell align="right">{consentStats.total}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><ColorBox color="#4caf50" /></TableCell>
                      <TableCell> Approved</TableCell>
                      <TableCell align="right">{consentStats.approved}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><ColorBox color="#ff9800" /></TableCell>
                      <TableCell> Pending</TableCell>
                      <TableCell align="right">{consentStats.pending}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><ColorBox color="#f44336" /></TableCell>
                      <TableCell> Rejected</TableCell>
                      <TableCell align="right">{consentStats.rejected}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><ColorBox color="#9e9e9e" /></TableCell>
                      <TableCell> Revoked</TableCell>
                      <TableCell align="right">{consentStats.revoked}</TableCell>
                    </TableRow>
                  </TableBody>
                </Table>
              </Box>
            </Card>
          </Grid>

          {/* Grievance */}
          <Grid item xs={12} md={6}>
            <Card elevation={5} sx={{ p: 3, display: 'flex', flexDirection: isSmallScreen ? 'column' : 'row', gap: 3 }}>
              <Box sx={{ width: isSmallScreen ? '100%' : '50%', height: 250 }}>
                <Doughnut data={grievanceChartData} options={chartOptions} />
              </Box>
              <Box sx={{ flex: 1 }}>
                <Typography color="primary" gutterBottom sx={{fontSize:'16px',textAlign:'center'}}>
                  Grievance Summary
                </Typography>
                <Table size="small">
                  <TableBody>
                    <TableRow>
                      <TableCell></TableCell>
                      <TableCell>Total</TableCell>
                      <TableCell align="right">{grievanceStats.total}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><ColorBox color="#ffb300" /></TableCell>
                      <TableCell> Pending</TableCell>
                      <TableCell align="right">{grievanceStats.pending}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><ColorBox color="#4caf50" /></TableCell>
                      <TableCell> Resolved</TableCell>
                      <TableCell align="right">{grievanceStats.resolved}</TableCell>
                    </TableRow>
                  </TableBody>
                </Table>
              </Box>
            </Card>
          </Grid>
        </Grid>
      </Box>

      {/* Awareness Boxes */}
      <Box
        sx={{
          mt: 5,
          px: 2,
          width: '100%',
          display: 'flex',
          flexDirection: isSmallScreen ? 'column' : 'row',
          gap: 3,
          justifyContent: 'center',
          alignItems: 'stretch',
          maxWidth: 1100,
          mx: 'auto',
        }}
      >
        <DPDPOrgAwarenessBox />
        <OrgResponsibilitiesBox />
      </Box>
    </Box>
  );
}

export default OrganizationDashboard;
