import React, { useState } from 'react';
import {
  Box,
  Typography,
  Card,
  Grid,
  List,
  ListItem,
  ListItemText,
  Divider,
  useTheme,
  useMediaQuery,
  Table,
  TableBody,
  TableRow,
  TableCell,
  Stack,
} from '@mui/material';
import { Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { useNavigate } from 'react-router-dom';
import AdminNavbar from './admin-navbar';

ChartJS.register(ArcElement, Tooltip, Legend);

// Color box component for table
function ColorBox({ color }) {
  return (
    <Box
      component="span"
      sx={{
        display: 'inline-block',
        width: 14,
        height: 14,
        backgroundColor: color,
        borderRadius: '3px',
        mr: 1,
        border: '1px solid #ccc',
      }}
    />
  );
}

function AdminDashboard() {
  const theme = useTheme();
  const isSmallScreen = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();

  const [consentStats] = useState({
    total: 20,
    accepted: 8,
    pending: 5,
    rejected: 4,
    revoked: 3,
  });

  const [orgDataAccess] = useState({
    'Health Insurance': 10,
    'Housing Loan': 6,
    'Deposits': 4,
  });

  const [grievanceStats] = useState({
    total: 5,
    pending: 2,
    resolved: 3,
  });

  const [recentActivities] = useState([
    {
      id: 1,
      action: 'Accepted',
      company: 'Health Insurance',
      user: 'user1@example.com',
      date: '2025-06-09 10:12',
    },
    {
      id: 2,
      action: 'Rejected',
      company: 'Housing Loan',
      user: 'user2@example.com',
      date: '2025-06-09 09:43',
    }
  ]);

  const consentColors = {
    Accepted: '#388e3c',
    Pending: '#f57c00',
    Rejected: '#d32f2f',
    Revoked: '#616161',
  };

  const orgColors = ['#42a5f5', '#7e57c2', '#26a69a'];

  const grievanceColors = {
    Pending: '#ffb300',
    Resolved: '#4caf50',
  };

  const chartOptions = {
    plugins: {
      legend: {
        display: false,
      },
    },
    maintainAspectRatio: false,
  };

  const consentChartData = {
    labels: Object.keys(consentColors),
    datasets: [
      {
        data: [
          consentStats.accepted,
          consentStats.pending,
          consentStats.rejected,
          consentStats.revoked,
        ],
        backgroundColor: Object.values(consentColors),
      },
    ],
  };

  const orgAccessChartData = {
    labels: Object.keys(orgDataAccess),
    datasets: [
      {
        data: Object.values(orgDataAccess),
        backgroundColor: orgColors,
      },
    ],
  };

  const grievanceChartData = {
    labels: Object.keys(grievanceColors),
    datasets: [
      {
        data: [grievanceStats.pending, grievanceStats.resolved],
        backgroundColor: Object.values(grievanceColors),
      },
    ],
  };

  // const fixedCardHeight = 320;

  const renderChartCard = (title, chartData, colorsMap, dataMap, totalLabel = null) => (
    <Card elevation={5} sx={{ p: 2,  display: 'flex' }}>
      {/* Chart Left */}
      <Box sx={{ width: 230, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Doughnut data={chartData} options={chartOptions} />
      </Box>

      {/* Table Right */}
      <Box sx={{ flex: 1, pl: 2 }}>
        <Typography color="primary" gutterBottom sx={{fontSize:'16px',textAlign:'center'}}>
          {title}
        </Typography>
        <Table size="small">
          <TableBody>
            {totalLabel && (
              <TableRow>
                <TableCell>Total</TableCell>
                <TableCell align="right">{totalLabel}</TableCell>
              </TableRow>
            )}
            {Object.entries(colorsMap).map(([key, color], index) => (
              <TableRow key={key}>
                <TableCell>
                  <ColorBox color={color} />
                  {key}
                </TableCell>
                <TableCell align="right">
                  {dataMap[key.toLowerCase()] || dataMap[key]}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Box>
    </Card>
  );

  return (
    <Box>
      <AdminNavbar />
      <Box sx={{ mt: 3, textAlign: 'center' }}>
        <Typography variant="h4" fontWeight="bold">
          👋 Hi, Admin!
        </Typography>
        <Typography variant="subtitle1" color="textSecondary">
          Welcome back to your CMS Admin Dashboard
        </Typography>
      </Box>

      {/* 3 Charts in a Row */}
      <Box sx={{ mt: 5, px: 3 }}>
        <Stack
          direction={isSmallScreen ? 'column' : 'row'}
          spacing={3}
          justifyContent="center"
          alignItems="stretch"
        >
          {renderChartCard(
            'Consent Summary',
            consentChartData,
            consentColors,
            consentStats,
            consentStats.total
          )}
          {renderChartCard(
            'Data Access by Department Summary',
            orgAccessChartData,
            Object.fromEntries(Object.keys(orgDataAccess).map((org, i) => [org, orgColors[i]])),
            orgDataAccess
          )}
          {renderChartCard(
            'Grievance Summary',
            grievanceChartData,
            grievanceColors,
            grievanceStats,
            grievanceStats.total
          )}
        </Stack>
      </Box>

      {/* DPDP Awareness + Recent Activities */}
      <Box sx={{ mt: 5, mx: 'auto', px: 2, maxWidth: 1100 }}>
        <Grid container spacing={4}>
          {/* Awareness */}
          <Grid item xs={12} md={6}>
           
            <Card
              sx={{
                p: 3,
                borderRadius: 2,
                border: '1px solid rgb(17, 1, 1)',
                boxShadow: 2,
                backgroundColor: '#f3f6f9',
              }}
            >
               <Typography variant="h6" fontWeight="bold" gutterBottom color="primary">
                🛡️ DPDP Admin Responsibilities
              </Typography>
              <Typography variant="body1" sx={{ mb: 1 }}>
                • Ensure consent requests are legitimate and compliant with the DPDP Act.
              </Typography>
              <Typography variant="body1" sx={{ mb: 1 }}>
                • Monitor how user data is accessed and by whom.
              </Typography>
              <Typography variant="body1">
                • Address grievances promptly and document actions taken.
              </Typography>
            </Card>
          </Grid>

          {/* Activity */}
          <Grid item xs={12} md={6} sx={{borderRadius: 2, boxShadow: 2,  border: '1px solid rgb(17, 1, 1)'}}>
            <Typography variant="h6" fontWeight="bold" gutterBottom>
              🕒 Recent Consent Activity
            </Typography>
            <Card sx={{ p: 2 }}>
              <List dense>
                {recentActivities.map((activity, index) => (
                  <Box key={activity.id}>
                    <ListItem>
                      <ListItemText
                        primary={`${activity.action} by ${activity.company}`}
                        secondary={`User: ${activity.user} • ${activity.date}`}
                      />
                    </ListItem>
                    {index < recentActivities.length - 1 && <Divider />}
                  </Box>
                ))}
              </List>
            </Card>
          </Grid>
        </Grid>
      </Box>
    </Box>
  );
}

export default AdminDashboard;
