import React, { useState } from 'react';
import {
  Box,
  Typography,
  TextField,
  Button,
  Checkbox,
  FormControlLabel,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import UserNavbar from './user-navbar';

function ProfileSettings() {
  const [mobileNumber, setMobileNumber] = useState('+919999988888');
  const [isChangingIdentifier, setIsChangingIdentifier] = useState(false);
  const [newNumber, setNewNumber] = useState('');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [consentUpdatesEmail, setConsentUpdatesEmail] = useState(false);
  const [newPolicyNotifications, setNewPolicyNotifications] = useState(false);
  const [otpDialogOpen, setOtpDialogOpen] = useState(false);

  const handleStartChange = () => {
    setIsChangingIdentifier(true);
  };

  const handleSendOtp = () => {
    if (!newNumber) {
      alert('Please enter a new mobile number');
      return;
    }
    setOtpSent(true);
    setOtpDialogOpen(true);
    // Simulate OTP send
    alert(`OTP sent to ${newNumber}`);
  };

  const handleConfirmOtp = () => {
    if (!otp) {
      alert('Please enter OTP');
      return;
    }
    // For demo, assume OTP is always correct
    setMobileNumber(newNumber);
    setIsChangingIdentifier(false);
    setNewNumber('');
    setOtp('');
    setOtpSent(false);
    setOtpDialogOpen(false);
    alert('Mobile number updated successfully');
  };

  const handleSaveSettings = () => {
    // Save notification preferences here
    alert('Settings saved');
  };

  return (
    <>
    <UserNavbar />
    <Box
      sx={{
        maxWidth: 480,
        mx: 'auto',
        mt: 5,
        p: 4,
        border: '1px solid #ccc',
        borderRadius: 2,
        bgcolor: 'background.paper',
      }}
    >
      <Typography variant="h5" align="center" gutterBottom fontWeight="bold">
        PROFILE SETTINGS
      </Typography>

      <Divider sx={{ mb: 3 }} />

      <Typography variant="subtitle1" gutterBottom>
        User Identifier:
      </Typography>

      <Typography variant="body1" sx={{ mb: 1 }}>
        {mobileNumber} (Mobile)
      </Typography>

      
      <Typography variant="subtitle1" gutterBottom>
        Notification Preferences:
      </Typography>

      <FormControlLabel
        control={
          <Checkbox
            checked={consentUpdatesEmail}
            onChange={(e) => setConsentUpdatesEmail(e.target.checked)}
          />
        }
        label="Receive consent updates via email"
      />
      <FormControlLabel
        control={
          <Checkbox
            checked={newPolicyNotifications}
            onChange={(e) => setNewPolicyNotifications(e.target.checked)}
          />
        }
        label="Receive notifications on new policies"
      />

      <Box sx={{ mt: 4 }}>
        <Button variant="contained" fullWidth onClick={handleSaveSettings} sx={{background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)'}}>
          Save Settings
        </Button>
      </Box>

      {/* Optional OTP Confirmation Dialog */}
      <Dialog open={otpDialogOpen} onClose={() => setOtpDialogOpen(false)}>
        <DialogTitle>OTP Sent</DialogTitle>
        <DialogContent>
          <Typography>
            An OTP has been sent to {newNumber}. Please enter it above to confirm your new mobile number.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button  onClick={() => setOtpDialogOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Box>
    </>
  );
}

export default ProfileSettings;
