import React, { useState, useRef, useEffect } from 'react';
import {
  Tabs,
  Tab,
  Box,
  TextField,
  Button,
  MenuItem,
  Typography,
  useMediaQuery,
  useTheme,
  Container,
  Divider,
  Link,
} from '@mui/material';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';

import { useNavigate } from 'react-router-dom';
import SecurityImg from '../static/images/login-security.jpg';

function DPDPInfoBox() {
  return (
    <Box
      sx={{
        mt: 2,
        p: 4,
        border: '1px solid #1976d2',
        borderRadius: 3,
        backgroundColor: '#e3f2fd',
        boxShadow: 3,
      }}
    >
      <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#0d47a1', mb: 2 }}>
        Your Data, Your Control – Powered by the DPDP Act
      </Typography>
      <Typography variant="body1" color="text.primary" sx={{ mb: 2 }}>
        This centralized <strong>Consent Management System (CMS)</strong> is designed in compliance with the{' '}
        <strong>Digital Personal Data Protection (DPDP) Act, 2023</strong>. It enables individuals and organizations to manage, review, and update their data sharing consents in a secure and transparent way.
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        You have full control over how your personal data is collected and used. The DPDP Act empowers you to give, deny, or withdraw consent at any time.
      </Typography>
      <Link href="/dpdp-info" target="_blank" rel="noopener" underline="hover">
        Learn more about your data rights →
      </Link>
    </Box>
  );
}

function LoginTabs() {
  const [tabIndex, setTabIndex] = useState(0);
  const [adminUsername, setAdminUsername] = useState('');
  const [adminPassword, setAdminPassword] = useState('');
  const [userNumber, setUserNumber] = useState('');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [orgUsername, setOrgUsername] = useState('');
  const [orgOtp, setOrgOtp] = useState('');
  const [orgOtpSent, setOrgOtpSent] = useState(false);
  const loginBoxRef = useRef(null);
  const imageBoxRef = useRef(null);
  const [containerHeight, setContainerHeight] = useState('auto');
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [forgotModalOpen, setForgotModalOpen] = useState(false);
  const [forgotUsername, setForgotUsername] = useState('');
  const [forgotOtpSent, setForgotOtpSent] = useState(false);
  const [forgotOtp, setForgotOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const handleSendForgotOtp = () => {
    if (!forgotUsername) return alert('Please enter your email/username');
    setForgotOtpSent(true);
    alert('OTP sent to your registered email/mobile');
  };

  const handleResetPassword = () => {
    if (!forgotOtp || !newPassword || !confirmPassword) return alert('All fields are required');
    if (newPassword !== confirmPassword) return alert('Passwords do not match');
    alert('Password reset successfully');
    setForgotModalOpen(false);
    // Reset state
    setForgotUsername('');
    setForgotOtp('');
    setNewPassword('');
    setConfirmPassword('');
    setForgotOtpSent(false);
  };



  const handleTabChange = (event, newValue) => {
    setTabIndex(newValue);
    setOtpSent(false);
    setOtp('');
    setOrgOtp('');
    setOrgOtpSent(false);
  };

  const handleAdminLogin = () => {
    if (!adminUsername || !adminPassword) return alert('Please enter username & password');
    navigate('/admin-dashboard');
  };

  const handleSendOtp = () => {
    if (!userNumber) return alert('Please enter your number');
    setOtpSent(true);
    alert('OTP sent to your Email/Mobile');
  };

  const handleUserSubmit = () => {
    if (!otp) return alert('Please enter OTP');
    navigate('/user-dashboard');
  };

  const handleSendOrgOtp = () => {
    if (!orgUsername) return alert('Please enter organization email');
    setOrgOtpSent(true);
    alert('OTP sent to your registered email');
  };

  const handleOrgSubmit = () => {
    if (!orgOtp) return alert('Please enter OTP');
    navigate('/organization-dashboard');
  };

  const renderLoginForm = () => (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
      {tabIndex === 0 && (
        <>
          <TextField label="Username" value={adminUsername} onChange={(e) => setAdminUsername(e.target.value)} fullWidth />
          <TextField label="Password" type="password" value={adminPassword} onChange={(e) => setAdminPassword(e.target.value)} fullWidth />
          <Button variant="contained" onClick={handleAdminLogin}>Login</Button>
          <Box sx={{ textAlign: "right" }}>
            Forgot Password?{' '}
            <i
              style={{ color: "blue", cursor: "pointer" }}
              onClick={() => setForgotModalOpen(true)}
            >
              Reset
            </i>
          </Box>

        </>
      )}
      {tabIndex === 1 && (
        <>
          <TextField label="Email/Mobile" value={userNumber} onChange={(e) => setUserNumber(e.target.value)} fullWidth />
          {!otpSent ? (
            <Button variant="contained" onClick={handleSendOtp}>Send OTP</Button>
          ) : (
            <>
              <TextField label="Enter OTP" value={otp} onChange={(e) => setOtp(e.target.value)} fullWidth />
              <Button variant="contained" onClick={handleUserSubmit}>Login</Button>
            </>
          )}
        </>
      )}
      {tabIndex === 2 && (
        <>
          <TextField label="Email" value={orgUsername} onChange={(e) => setOrgUsername(e.target.value)} fullWidth />
          {!orgOtpSent ? (
            <Button variant="contained" onClick={handleSendOrgOtp}>Send OTP</Button>
          ) : (
            <>
              <TextField label="Enter OTP" value={orgOtp} onChange={(e) => setOrgOtp(e.target.value)} fullWidth />
              <Button variant="contained" onClick={handleOrgSubmit}>Login</Button>
            </>
          )}

          <Box sx={{ textAlign: "right" }}>
            New Organization? <i style={{ color: "blue", cursor: "pointer" }} onClick={() => navigate('/organization-onboarding-form')}>Register</i>
          </Box>

          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Divider sx={{ flex: 1 }} />
            <Typography variant="body2" sx={{ mx: 2, color: 'text.secondary' }}>
              OR
            </Typography>
            <Divider sx={{ flex: 1 }} />
          </Box>

          <Button
            variant="outlined"
            fullWidth
            sx={{ textTransform: 'none' }}
            onClick={() => alert('Login with your Gmail/Microsoft Account')}
          >
            Login with SSO
          </Button>
        </>
      )}
    </Box>
  );

  useEffect(() => {
    if (loginBoxRef.current && imageBoxRef.current) {
      const loginHeight = loginBoxRef.current.offsetHeight;
      const imageHeight = imageBoxRef.current.offsetHeight;
      setContainerHeight(Math.max(loginHeight, imageHeight));
    }
  }, [tabIndex, adminUsername, adminPassword, otp, otpSent, userNumber, orgUsername, orgOtp, orgOtpSent, isMobile]);

  return (
    <Container maxWidth="lg" sx={{ py: 2 }}>
      <Box
        sx={{
          display: 'flex',
          flexDirection: isMobile ? 'column' : 'row',
          border: '1px solid #ccc',
          borderRadius: 3,
          boxShadow: 3,
          overflow: 'hidden',
          height: isMobile ? 'auto' : containerHeight,
          width: '100%',
          bgcolor: '#fff',
        }}
      >
        <Box
          ref={loginBoxRef}
          sx={{
            flex: 1,
            p: 4,
            boxSizing: 'border-box',
            display: 'flex',
            flexDirection: 'column',
          }}
        >
          <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 3 }}>
            CMS Login
          </Typography>
          <Tabs
            value={tabIndex}
            onChange={handleTabChange}
            variant="fullWidth"
            textColor="primary"
            indicatorColor="primary"
            sx={{ mb: 2 }}
          >
            <Tab label="Admin" />
            <Tab label="User" />
            <Tab label="Department" />
          </Tabs>

          <Box sx={{ flexGrow: 1 }}>{renderLoginForm()}</Box>

          <Typography variant="caption" sx={{ mt: 'auto', color: 'text.secondary', userSelect: 'none', pt: 2 }}>
            By logging in, you acknowledge our commitment to the DPDP Act and your data privacy rights.
          </Typography>
        </Box>

        {!isMobile && (
          <Divider
            orientation="vertical"
            flexItem
            sx={{ bgcolor: '#ddd', width: '1px' }}
          />
        )}

        <Box
          ref={imageBoxRef}
          sx={{
            flex: 1,
            p: 2,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            boxSizing: 'border-box',
          }}
        >
          <img
            src={SecurityImg}
            alt="Data Security"
            style={{ maxWidth: '100%', maxHeight: '100%', borderRadius: 8 }}
          />
        </Box>
      </Box>

      <DPDPInfoBox />
      <Dialog open={forgotModalOpen} onClose={() => setForgotModalOpen(false)} maxWidth="xs" fullWidth>
        <DialogTitle>Reset Admin Password</DialogTitle>
        <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
          <TextField
            label="Username / Email"
            fullWidth
            value={forgotUsername}
            onChange={(e) => setForgotUsername(e.target.value)}
          />
          {!forgotOtpSent ? (
            <Button variant="contained" onClick={handleSendForgotOtp}>
              Send OTP
            </Button>
          ) : (
            <>
              <TextField
                label="Enter OTP"
                fullWidth
                value={forgotOtp}
                onChange={(e) => setForgotOtp(e.target.value)}
              />
              <TextField
                label="New Password"
                type="password"
                fullWidth
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
              />
              <TextField
                label="Confirm Password"
                type="password"
                fullWidth
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
              />
              <Button variant="contained" onClick={handleResetPassword}>
                Reset Password
              </Button>
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setForgotModalOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>

    </Container>
  );
}

export default LoginTabs;
