import React from 'react';
import {
  Box,
  Typography,
  Card,
  useMediaQuery,
  useTheme,
  Tooltip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Stack,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import UserNavbar from './user-navbar';

import { Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip as ChartTooltip,
  Legend,
} from 'chart.js';

ChartJS.register(ArcElement, ChartTooltip, Legend);

// Utility function to darken a color
function shadeColor(color, percent) {
  let f = parseInt(color.slice(1), 16),
    t = percent < 0 ? 0 : 255,
    p = Math.abs(percent) / 100,
    R = f >> 16,
    G = (f >> 8) & 0x00ff,
    B = f & 0x0000ff;
  return (
    '#' +
    (
      0x1000000 +
      (Math.round((t - R) * p) + R) * 0x10000 +
      (Math.round((t - G) * p) + G) * 0x100 +
      (Math.round((t - B) * p) + B)
    )
      .toString(16)
      .slice(1)
  );
}

function DPDPUserAwarenessBox() {
  return (
    <Box
      sx={{
        flex: 1,
        p: 3,
        border: '1px solid rgb(17, 1, 1)',
        backgroundColor: '#f9f9f9',
        borderRadius: 2,
        boxShadow: 1,
        minWidth: 280,
      }}
    >
      <Typography variant="h6" fontWeight="bold" gutterBottom color="primary">
        📢 Know Your Data Rights
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        ✅ Control your data-sharing consents.
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        ✅ View how your data is being used.
      </Typography>
      <Typography variant="body2">
        🔒 Stay informed and empowered under the DPDP Act.
      </Typography>
    </Box>
  );
}

function WhatYouCanDoBox() {
  return (
    <Box
      sx={{
        flex: 1,
        p: 3,
        border: '1px solid rgb(17, 1, 1)',
        backgroundColor: '#ffffff',
        borderRadius: 2,
        boxShadow: 1,
        minWidth: 280,
      }}
    >
      <Typography variant="h6" fontWeight="bold" gutterBottom>
        🛠️ What You Can Do Here
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        • View consents given to organizations.
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        • Monitor how and when your data is used.
      </Typography>
      <Typography variant="body2">
        • Revoke consent anytime. You’re in control.
      </Typography>
    </Box>
  );
}

function MetricsCard({ title, chartColors, data, onRowClick }) {
  const doughnutData = {
    labels: data.map((item) => item.label),
    datasets: [
      {
        data: data.map((item) => item.value),
        backgroundColor: chartColors,
        hoverBackgroundColor: chartColors.map((c) => shadeColor(c, -20)),
      },
    ],
  };

  const options = {
    plugins: {
      legend: {
        display: false,
      },
      tooltip: {
        enabled: true,
      },
    },
    maintainAspectRatio: false,
  };

  return (
    <Card
      sx={{
        p: 2,
        borderRadius: 2,
        boxShadow: 3,
        display: 'flex',
        minHeight: 320,
      }}
    >
      
      {/* Chart Left */}
      <Box sx={{ width: 230, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Doughnut data={doughnutData} options={options} />
      </Box>

      {/* Metrics Table Right */}
      <Box sx={{ flex: 1, pl: 2 }}>
        <Typography color="primary" gutterBottom sx={{fontSize:'16px',textAlign:'center'}}>
          {title}
        </Typography>
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell><strong>Category</strong></TableCell>
                <TableCell align="right"><strong>Count</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {data.map(({ label, value }, index) => (
                <TableRow
                  key={index}
                  hover={!!onRowClick}
                  onClick={() => onRowClick && onRowClick(label)}
                  sx={{ cursor: onRowClick ? 'pointer' : 'default' }}
                >
                  <TableCell sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Box
                      sx={{
                        width: 12,
                        height: 12,
                        backgroundColor: chartColors[index],
                        borderRadius: '3px',
                        border: '1px solid #ccc',
                      }}
                    />
                    {label}
                  </TableCell>
                  <TableCell align="right">{value}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Box>
    </Card>
  );
}

function UserDashboard() {
  const navigate = useNavigate();
  const theme = useTheme();
  const isSmallScreen = useMediaQuery(theme.breakpoints.down('sm'));

  const consentMetrics = [
    { label: 'Approved', value: 4 },
    { label: 'Pending', value: 1 },
    { label: 'Rejected', value: 2 },
    { label: 'Revoked', value: 1 },
  ];

  const dataAccessMetrics = [
    { label: 'HealthCare Inc.', value: 2 },
    { label: 'EduLearn', value: 1 },
    { label: 'FitTrack', value: 1 },
  ];

  const grievanceMetrics = [
    { label: 'Resolved', value: 3 },
    { label: 'Pending', value: 1 },
  ];

  const consentColors = ['#4caf50', '#ff9800', '#f44336', '#9e9e9e'];
  const dataAccessColors = ['#2196f3', '#3f51b5', '#00bcd4'];
  const grievanceColors = ['#4caf50', '#ff9800'];

  return (
    <Box>
      <UserNavbar />
      <Box sx={{ mt: 3, textAlign: 'center' }}>
        <Typography variant="h4" fontWeight="bold">
          👋 Hi, User!
        </Typography>
        <Typography variant="subtitle1" color="textSecondary">
          Welcome to CMS, you can manage consent here
        </Typography>
        
      </Box>

      {/* Chart + Metrics Cards */}
      <Box sx={{ mt: 4, px: 2, width: '100%', maxWidth: 1400, mx: 'auto' }}>
        <Stack
          direction={isSmallScreen ? 'column' : 'row'}
          spacing={3}
          justifyContent="center"
          alignItems="stretch"
        >
          <Tooltip title="View Consent Details" arrow>
            <Box sx={{ flex: 1 }}>
              <MetricsCard
                title="Consent Summary"
                data={consentMetrics}
                chartColors={consentColors}
                onRowClick={() => navigate('/user-consent-details')}
              />
            </Box>
          </Tooltip>

          <Tooltip title="View Data Access Details" arrow>
            <Box sx={{ flex: 1 }}>
              <MetricsCard
                title="Data Access by Department Summary"
                data={dataAccessMetrics}
                chartColors={dataAccessColors}
                onRowClick={() => navigate('/user-consent-details')}
              />
            </Box>
          </Tooltip>

          <Tooltip title="View Grievances" arrow>
            <Box sx={{ flex: 1 }}>
              <MetricsCard
                title="Grievance Summary"
                data={grievanceMetrics}
                chartColors={grievanceColors}
                onRowClick={() => navigate('/user-consent-details')}
              />
            </Box>
          </Tooltip>
        </Stack>
      </Box>

      {/* Awareness Boxes */}
      <Box
        sx={{
          mt: 4,
          px: 2,
          display: 'flex',
          flexDirection: isSmallScreen ? 'column' : 'row',
          gap: 3,
          justifyContent: 'center',
          maxWidth: 1000,
          mx: 'auto',
        }}
      >
        <DPDPUserAwarenessBox />
        <WhatYouCanDoBox />
      </Box>
    </Box>
  );
}

export default UserDashboard;
