import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TextField,
  TablePagination,
} from '@mui/material';
import UserNavbar from './user-navbar';

function DPDPInfoBox() {
  return (
    <Box
      sx={{
        width: '97%',
        margin: 'auto',
        mb: 3,
        p: 2,
        border: '1px solid #e0e0e0',
        borderRadius: 2,
        backgroundColor: '#fff8e1',
        boxShadow: 1,
      }}
    >
      <Typography variant="body1" fontWeight="bold" gutterBottom>
        🛡️ DPDP Awareness
      </Typography>
      <Typography variant="body2">
        The <strong>DPDP Act</strong> ensures transparency and control over your personal data. All your activities related to data consents and grievances are logged here for your reference.
      </Typography>
    </Box>
  );
}

function UserAuditLogs() {
  const [logs, setLogs] = useState([
    {
      id: 1,
      timestamp: '2025-06-01 09:15 AM',
      action: 'Consent Given',
      organization: 'Housing Loan',
      purpose: 'Name Verification',
      details: 'Consent granted for name verification.',
      metadata: 'IP: 192.168.0.1 | Device: Chrome on Android | Location: Bangalore',
    },
    {
      id: 2,
      timestamp: '2025-06-07 11:00 AM',
      action: 'Data Usage Reported',
      organization: 'Account Opening',
      purpose: 'KYC',
      details: 'Reported unauthorized data usage.',
      metadata: 'IP: 10.0.0.2 | Device: Firefox on Windows | Location: Chennai',
    },
    {
      id: 3,
      timestamp: '2025-04-01 10:30 AM',
      action: 'Consent Revoked',
      organization: 'Deposits',
      purpose: 'DOB Verification',
      details: 'User revoked DOB Verification consent.',
      metadata: 'IP: 172.16.1.10 | Device: Safari on iOS | Location: Bangalore',
    },
    // Add more sample logs if needed
  ]);

  const [searchText, setSearchText] = useState('');
  const [filteredLogs, setFilteredLogs] = useState(logs);

  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  useEffect(() => {
    const filtered = logs.filter((log) =>
      [log.organization, log.purpose, log.action, log.details, log.metadata]
        .some(field => field.toLowerCase().includes(searchText.toLowerCase()))
    );
    setFilteredLogs(filtered);
    setPage(0);
  }, [searchText, logs]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Box>
      <UserNavbar />
      <Box sx={{ width: '90%', margin: 'auto', mt: 4 }}>
        <Typography variant="h6" fontWeight="bold" gutterBottom>
          📝 Audit Logs
        </Typography>
        <Typography variant="body2" sx={{ mb: 3 }}>
          View a chronological log of your actions related to consents and data usage reports for transparency and record-keeping.
        </Typography>
        <DPDPInfoBox />
        <TextField
          label="Search Logs"
          variant="outlined"
          fullWidth
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          sx={{ mb: 3 }}
          placeholder="Search by deparment, purpose, action, details, or metadata"
        />

        <TableContainer component={Paper} elevation={4}>
          <Table>
            <TableHead>
              <TableRow sx={{ background: 'linear-gradient(90deg, #1e3c72, #2a5298)' }}>
                <TableCell sx={{ color: 'white' }}>Timestamp</TableCell>
                <TableCell sx={{ color: 'white' }}>Action</TableCell>
                <TableCell sx={{ color: 'white' }}>Department</TableCell>
                <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
                <TableCell sx={{ color: 'white' }}>Details</TableCell>
                <TableCell sx={{ color: 'white' }}>Metadata</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredLogs.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    No audit logs found.
                  </TableCell>
                </TableRow>
              ) : (
                filteredLogs
                  .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                  .map((log) => (
                    <TableRow key={log.id}>
                      <TableCell>{log.timestamp}</TableCell>
                      <TableCell>{log.action}</TableCell>
                      <TableCell>{log.organization}</TableCell>
                      <TableCell>{log.purpose}</TableCell>
                      <TableCell>{log.details}</TableCell>
                      <TableCell>{log.metadata}</TableCell>
                    </TableRow>
                  ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          component="div"
          count={filteredLogs.length}
          page={page}
          onPageChange={handleChangePage}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          rowsPerPageOptions={[5, 10, 25]}
          sx={{ mt: 2 }}
        />
      </Box>
    </Box>
  );
}

export default UserAuditLogs;
