import React, { useState } from 'react';
import {
  Box,
  Typography,
  Card,
  Table,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  MenuItem,
  IconButton,
  Menu,
  TablePagination,
  Stack,
} from '@mui/material';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import AdminNavbar from './admin-navbar';
import { v4 as uuidv4 } from 'uuid';

const roles = [
  { value: 'admin', label: 'Admin' },
  { value: 'consent_manager', label: 'Consent Manager' },
  { value: 'grievance_manager', label: 'Grievance Manager' },
  { value: 'others', label: 'Others' },
];

const sampleUsers = [
  { id: uuidv4(), name: 'Alice', email: 'alice@example.com', role: 'admin' },
  { id: uuidv4(), name: 'Bob', email: 'bob@example.com', role: 'consent_manager' },
  { id: uuidv4(), name: 'Charlie', email: 'charlie@example.com', role: 'grievance_manager' },
  { id: uuidv4(), name: 'David', email: 'david@example.com', role: 'admin' },
  { id: uuidv4(), name: 'Eva', email: 'eva@example.com', role: 'consent_manager' },
  { id: uuidv4(), name: 'Frank', email: 'frank@example.com', role: 'grievance_manager' },
  { id: uuidv4(), name: 'Grace', email: 'grace@example.com', role: 'admin' },
  { id: uuidv4(), name: 'Helen', email: 'helen@example.com', role: 'consent_manager' },
  { id: uuidv4(), name: 'Ivy', email: 'ivy@example.com', role: 'grievance_manager' },
  { id: uuidv4(), name: 'Jack', email: 'jack@example.com', role: 'admin' },
];

function AdminManageUsersPage() {
  const [users, setUsers] = useState(sampleUsers);
  const [openDialog, setOpenDialog] = useState(false);
  const [formMode, setFormMode] = useState('add');
  const [currentUser, setCurrentUser] = useState({ id: '', name: '', email: '', role: '' });
  const [search, setSearch] = useState('');
  const [anchorEl, setAnchorEl] = useState(null);
  const [menuUserId, setMenuUserId] = useState(null);
  const [page, setPage] = useState(0);
  const rowsPerPage = 5;

  const handleOpenAdd = () => {
    setFormMode('add');
    setCurrentUser({ id: '', name: '', email: '', role: '' });
    setOpenDialog(true);
  };

  const handleOpenEdit = (user) => {
    setFormMode('edit');
    setCurrentUser(user);
    setOpenDialog(true);
    handleCloseMenu();
  };

  const handleDelete = (id) => {
    setUsers(users.filter((u) => u.id !== id));
    handleCloseMenu();
  };

  const handleSave = () => {
    if (formMode === 'add') {
      setUsers([...users, { ...currentUser, id: uuidv4() }]);
    } else {
      setUsers(users.map((u) => (u.id === currentUser.id ? currentUser : u)));
    }
    setOpenDialog(false);
  };

  const handleOpenMenu = (event, userId) => {
    setAnchorEl(event.currentTarget);
    setMenuUserId(userId);
  };

  const handleCloseMenu = () => {
    setAnchorEl(null);
    setMenuUserId(null);
  };

  const filteredUsers = users.filter(
    (u) =>
      u.name.toLowerCase().includes(search.toLowerCase()) ||
      u.email.toLowerCase().includes(search.toLowerCase())
  );

  const paginatedUsers = filteredUsers.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  return (
    <Box>
      <AdminNavbar />
      <Box sx={{ mt: 4, px: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Box>
            <Typography variant="h4" fontWeight="bold">Manage Users</Typography>
            <Typography variant="subtitle1" color="textSecondary">Assign roles, create or remove users</Typography>
          </Box>
          <Button variant="contained" onClick={handleOpenAdd}>
            Add User
          </Button>
        </Box>

        <TextField
          label="Search user"
          variant="outlined"
          size="small"
          fullWidth
          sx={{ mb: 2 }}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <Card>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Name</TableCell>
                <TableCell>Email</TableCell>
                <TableCell>Role</TableCell>
                <TableCell align="right"></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedUsers.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>{user.name}</TableCell>
                  <TableCell>{user.email}</TableCell>
                  <TableCell>{roles.find((r) => r.value === user.role)?.label}</TableCell>
                  <TableCell align="right">
                    <IconButton onClick={(e) => handleOpenMenu(e, user.id)}>
                      <MoreVertIcon />
                    </IconButton>
                    <Menu
                      anchorEl={anchorEl}
                      open={menuUserId === user.id}
                      onClose={handleCloseMenu}
                    >
                      <MenuItem onClick={() => handleOpenEdit(user)}>Edit</MenuItem>
                      <MenuItem onClick={() => handleDelete(user.id)}>Delete</MenuItem>
                    </Menu>
                  </TableCell>
                </TableRow>
              ))}
              {paginatedUsers.length === 0 && (
                <TableRow>
                  <TableCell colSpan={4} align="center">
                    No matching users found.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>

          <TablePagination
            component="div"
            count={filteredUsers.length}
            page={page}
            onPageChange={(e, newPage) => setPage(newPage)}
            rowsPerPage={rowsPerPage}
            rowsPerPageOptions={[rowsPerPage]}
          />
        </Card>
      </Box>

      {/* Dialog for Add/Edit */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{formMode === 'add' ? 'Add New User' : 'Edit User'}</DialogTitle>
        <DialogContent>
          <TextField
            margin="dense"
            label="Name"
            fullWidth
            value={currentUser.name}
            onChange={(e) => setCurrentUser({ ...currentUser, name: e.target.value })}
          />
          <TextField
            margin="dense"
            label="Email"
            fullWidth
            value={currentUser.email}
            onChange={(e) => setCurrentUser({ ...currentUser, email: e.target.value })}
          />
          <TextField
            margin="dense"
            select
            label="Role"
            fullWidth
            value={currentUser.role}
            onChange={(e) => setCurrentUser({ ...currentUser, role: e.target.value })}
          >
            {roles.map((r) => (
              <MenuItem key={r.value} value={r.value}>{r.label}</MenuItem>
            ))}
          </TextField>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleSave}>
            {formMode === 'add' ? 'Add' : 'Save'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

export default AdminManageUsersPage;
