import React, { useState } from 'react';
import {
  Box,
  Typography,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TablePagination,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Link,
} from '@mui/material';
import AdminNavbar from './admin-navbar';
import DownloadIcon from '@mui/icons-material/Download';
import { IconButton, Menu, MenuItem } from '@mui/material';
import MoreVertIcon from '@mui/icons-material/MoreVert';


function ConsentActionsMenu({ consent, handleViewConsentDetails, handleViewOrgDetails }) {
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };

  const onViewConsent = () => {
    handleViewConsentDetails(consent);
    handleClose();
  };

  const onViewOrg = () => {
    handleViewOrgDetails(consent.orgDetails);
    handleClose();
  };

  return (
    <>
      <IconButton
        size="small"
        aria-controls={open ? 'actions-menu' : undefined}
        aria-haspopup="true"
        aria-expanded={open ? 'true' : undefined}
        onClick={handleClick}
      >
        <MoreVertIcon />
      </IconButton>
      <Menu
        id="actions-menu"
        anchorEl={anchorEl}
        open={open}
        onClose={handleClose}
        MenuListProps={{
          'aria-labelledby': 'actions-button',
        }}
      >
        <MenuItem onClick={onViewConsent}>View Consent</MenuItem>
        <MenuItem onClick={onViewOrg}>Org Details</MenuItem>
      </Menu>
    </>
  );
}

// DPDP Awareness component for Admins
function DPDPAdminAwareness() {
  return (
    <Box
      sx={{
        width: '90%',
        margin: 'auto',
        mb: 4,
        p: 3,
        borderRadius: 2,
        backgroundColor: '#e3f2fd',
        boxShadow: 2,
        border: '1px solid #90caf9',
      }}
    >
      <Typography variant="h5" fontWeight="bold" gutterBottom>
        🛡️ DPDP Act: Admin Awareness
      </Typography>
      <Typography variant="body1" sx={{ mb: 1 }}>
        As an <strong>Administrator</strong>, you play a crucial role in ensuring compliance with the DPDP (Data Protection and Privacy) Act.
      </Typography>
      <Typography variant="body2" sx={{ mb: 1 }}>
        You are responsible for:
      </Typography>
      <ul>
        <li>Managing and overseeing user consents transparently.</li>
        <li>Ensuring data is used only for authorized purposes.</li>
        <li>Providing users the ability to revoke consents and handling requests promptly.</li>
        <li>Maintaining audit logs and consent histories as per DPDP compliance.</li>
      </ul>
      <Typography variant="body2">
        This dashboard allows you to view all consents granted by users and helps you monitor compliance efforts effectively.
      </Typography>
    </Box>
  );
}

function AdminTotalConsentPage() {
  const [consents, setConsents] = useState([
    {
      id: 1,
      user: 'Alice Johnson',
      org: 'Housing Loan',
      orgDetails: {
        name: 'Housing Loan',
        address: '123 Market Street, Cityville',
        contactEmail: 'contact@retailera.com',
        registrationNumber: 'REG-123456',
        phone: '+1-555-1234',
      },
      purpose: 'Name Verification',
      obtainValidConsent:'Free',
      status: 'Given',
      date: '2025-06-01',
      expiry: '2026-06-01',
      attachment: 'https://example.com/marketing-consent.pdf',
      history: {
        requested: '2025-05-30',
        accepted: '2025-06-01',
        revoked: null,
      },
    },
    {
      id: 2,
      user: 'Bob Smith',
      org: 'Account Opening',
      orgDetails: {
        name: 'Account Opening',
        address: '456 Finance Ave, Moneytown',
        contactEmail: 'support@bankb.com',
        registrationNumber: 'REG-654321',
        phone: '+1-555-5678',
      },
      purpose: 'KYC',
      obtainValidConsent:'Informed',
      status: 'Revoked',
      date: '2024-05-01',
      expiry: '2025-05-01',
      attachment: null,
      history: {
        requested: '2024-04-20',
        accepted: '2024-05-01',
        revoked: '2025-04-01',
      },
    },
    // Add more consents as needed
  ]);

  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(0);
  const rowsPerPage = 5;

  // Selected consent & dialogs states
  const [selectedConsent, setSelectedConsent] = useState(null);
  const [openViewDialog, setOpenViewDialog] = useState(false);

  // Selected org & dialog state
  const [selectedOrg, setSelectedOrg] = useState(null);
  const [openOrgDialog, setOpenOrgDialog] = useState(false);

  const filteredConsents = consents.filter(
    (c) =>
      c.user.toLowerCase().includes(searchText.toLowerCase()) ||
      c.org.toLowerCase().includes(searchText.toLowerCase()) ||
      c.purpose.toLowerCase().includes(searchText.toLowerCase()) ||
      c.status.toLowerCase().includes(searchText.toLowerCase())
  );

  const paginatedConsents = filteredConsents.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleViewConsentDetails = (consent) => {
    setSelectedConsent(consent);
    setOpenViewDialog(true);
  };

  const handleViewOrgDetails = (orgDetails) => {
    setSelectedOrg(orgDetails);
    setOpenOrgDialog(true);
  };

  const exportConsentsToCSV = () => {
    const headers = [
      'User',
      'Department',
      'Purpose',
      'Status',
      'Date',
      'Expiry',
      'Requested',
      'Accepted',
      'Revoked',
      'Attachment',
    ];

    const rows = filteredConsents.map(c => [
      c.user,
      c.org,
      c.purpose,
      c.status,
      c.date,
      c.expiry,
      c.history.requested,
      c.history.accepted,
      c.history.revoked || 'N/A',
      c.attachment || 'N/A',
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(r => r.map(v => `"${v}"`).join(',')),
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'user_consents.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };


  return (
    <>
        <AdminNavbar />
        <Box sx={{ width: '90%', margin: 'auto', mt: 4, mb: 6 }}>
      <DPDPAdminAwareness />

      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2, ml:1 }}>
          <Typography variant="h5" fontWeight="bold">
            Admin: User Level Consents
          </Typography>
          <Button variant="outlined" onClick={exportConsentsToCSV}>
            <DownloadIcon /> Export CSV
          </Button>
      </Box>


      <TextField
        label="Search consents by User, Department, Purpose, Status"
        variant="outlined"
        fullWidth
        value={searchText}
        onChange={(e) => {
          setSearchText(e.target.value);
          setPage(0);
        }}
        sx={{ mb: 3 }}
      />

      <TableContainer component={Paper} elevation={4}>
        <Table>
          <TableHead>
            <TableRow sx={{ background: 'linear-gradient(90deg, #1e3c72 0%, #2a5298 50%, #1e3c72 100%)', }}>
              <TableCell sx={{ color: 'white' }}>User</TableCell>
              <TableCell sx={{ color: 'white' }}>Department</TableCell>
              <TableCell sx={{ color: 'white' }}>Purpose</TableCell>
              <TableCell sx={{ color: 'white' }}>Obtain Valid Consent</TableCell>
              <TableCell sx={{ color: 'white' }}>Status</TableCell>
              <TableCell sx={{ color: 'white' }}>Date</TableCell>
              <TableCell sx={{ color: 'white' }}>Expiry</TableCell>
              <TableCell sx={{ color: 'white' }}></TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {paginatedConsents.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  No consents found.
                </TableCell>
              </TableRow>
            ) : (
              paginatedConsents.map((consent) => (
                <TableRow key={consent.id}>
                  <TableCell>{consent.user}</TableCell>
                  <TableCell>{consent.org}</TableCell>
                  <TableCell>{consent.purpose}</TableCell>
                  <TableCell>{consent.obtainValidConsent}</TableCell>
                  <TableCell>
                    <Typography
                      color={consent.status === 'Given' ? 'green' : 'error'}
                      fontWeight="bold"
                    >
                      {consent.status}
                    </Typography>
                  </TableCell>
                  <TableCell>{consent.date}</TableCell>
                  <TableCell>{consent.expiry}</TableCell>
                  <TableCell align="right">
                    <ConsentActionsMenu
                      consent={consent}
                      handleViewConsentDetails={handleViewConsentDetails}
                      handleViewOrgDetails={handleViewOrgDetails}
                    />
                  </TableCell>

                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <TablePagination
        component="div"
        count={filteredConsents.length}
        page={page}
        onPageChange={handleChangePage}
        rowsPerPage={rowsPerPage}
        rowsPerPageOptions={[]}
      />

      {/* Consent Details Dialog */}
      <Dialog
        open={openViewDialog}
        onClose={() => setOpenViewDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Consent Details</DialogTitle>
        <DialogContent dividers>
          {selectedConsent && (
            <>
              <Typography>
                <strong>User:</strong> {selectedConsent.user}
              </Typography>
              <Typography>
                <strong>Organization:</strong> {selectedConsent.org}
              </Typography>
              <Typography>
                <strong>Purpose:</strong> {selectedConsent.purpose}
              </Typography>
              <Typography>
                <strong>Obtain Valid Consent:</strong> {selectedConsent.obtainValidConsent}
              </Typography>
              <Typography>
                <strong>Status:</strong>{' '}
                <Typography
                  component="span"
                  color={selectedConsent.status === 'Given' ? 'green' : 'error'}
                  fontWeight="bold"
                >
                  {selectedConsent.status}
                </Typography>
              </Typography>
              <Typography>
                <strong>Date:</strong> {selectedConsent.date}
              </Typography>
              <Typography>
                <strong>Expiry:</strong> {selectedConsent.expiry}
              </Typography>
              <Typography sx={{ mt: 1 }}>
                <strong>Consent History:</strong>
              </Typography>
              <ul>
                <li>Requested: {selectedConsent.history.requested}</li>
                <li>Accepted: {selectedConsent.history.accepted}</li>
                <li>Revoked: {selectedConsent.history.revoked || 'N/A'}</li>
              </ul>
              {selectedConsent.attachment ? (
                <Link
                  href={selectedConsent.attachment}
                  target="_blank"
                  rel="noopener"
                >
                  View Attachment
                </Link>
              ) : (
                <Typography>No attachment available.</Typography>
              )}
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenViewDialog(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Organization Details Dialog */}
      <Dialog
        open={openOrgDialog}
        onClose={() => setOpenOrgDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Organization Details</DialogTitle>
        <DialogContent dividers>
          {selectedOrg && (
            <>
              <Typography><strong>Name:</strong> {selectedOrg.name}</Typography>
              <Typography><strong>Address:</strong> {selectedOrg.address}</Typography>
              <Typography><strong>Contact Email:</strong> {selectedOrg.contactEmail}</Typography>
              <Typography><strong>Phone:</strong> {selectedOrg.phone}</Typography>
              <Typography><strong>Registration Number:</strong> {selectedOrg.registrationNumber}</Typography>
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenOrgDialog(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Box>
    </>
    
  );
}

export default AdminTotalConsentPage;
